    static let all: [Cultivar] = rows.enumerated().compactMap { index, row in
        guard let species = SpeciesPreviewData.all.first(where: {
            $0.name.caseInsensitiveCompare(row.speciesName) == .orderedSame
        }) else {
            return nil
        }
        return Cultivar(
            id: id(speciesName: row.speciesName, cultivarName: row.name),
            name: row.name,
            speciesID: species.id,
            sortOrder: index + 1
        )
    }

    /// Stable Cultivar UUID — same formula as seed rows (list 3).
    static func id(speciesName: String, cultivarName: String) -> UUID {
        ReferencePreviewSeed.id(list: 3, named: "\(speciesName)|\(cultivarName)")
    }
